-- Creative Studio: run once in a new Supabase project's SQL Editor.
create extension if not exists pgcrypto;
create table public.classes (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id), name text not null check(length(name) between 1 and 100), invite_token text not null unique default encode(gen_random_bytes(24),'hex'), created_at timestamptz not null default now());
create table public.teams (id uuid primary key default gen_random_uuid(), class_id uuid not null references public.classes(id) on delete cascade, number int not null, join_code text not null default upper(substr(encode(gen_random_bytes(8),'hex'),1,12)), doc jsonb not null default '{"names":["",""],"stories":[[],[]],"ideas":[{},{}]}'::jsonb, version int not null default 0, updated_at timestamptz not null default now(), unique(class_id,number));
create table public.team_members (team_id uuid not null references public.teams(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, joined_at timestamptz not null default now(), primary key(team_id,user_id));
alter table public.classes enable row level security; alter table public.teams enable row level security; alter table public.team_members enable row level security;
-- Access to tables is exclusively through the narrowly scoped functions below.
revoke all on public.classes,public.teams,public.team_members from anon,authenticated;
create function public.is_admin() returns boolean language sql stable security definer set search_path=public,auth as $$ select auth.uid() is not null and coalesce((auth.jwt()->>'is_anonymous')::boolean,false)=false $$;
create function public.make_class(p_name text,p_count int) returns uuid language plpgsql security definer set search_path=public,auth as $$ declare c uuid; begin if not public.is_admin() then raise exception '관리자 로그인이 필요합니다'; end if; if length(trim(p_name)) not between 1 and 100 or p_count not between 1 and 30 then raise exception '클래스 이름과 조 수를 확인해 주세요'; end if; insert into public.classes(owner_id,name) values(auth.uid(),trim(p_name)) returning id into c; insert into public.teams(class_id,number) select c,generate_series(1,p_count); return c; end $$;
create function public.admin_classes() returns jsonb language sql security definer set search_path=public,auth as $$ select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'name',c.name,'token',c.invite_token,'created_at',c.created_at) order by c.created_at desc),'[]'::jsonb) from public.classes c where c.owner_id=auth.uid() and public.is_admin() $$;
create function public.admin_class(p_id uuid) returns jsonb language plpgsql security definer set search_path=public,auth as $$ declare out jsonb; begin if not public.is_admin() then raise exception '관리자 권한이 필요합니다'; end if; select jsonb_build_object('id',c.id,'name',c.name,'token',c.invite_token,'teams',coalesce((select jsonb_agg(jsonb_build_object('id',t.id,'number',t.number,'code',t.join_code,'doc',t.doc,'version',t.version,'updated_at',t.updated_at,'member_count',(select count(*) from public.team_members m where m.team_id=t.id)) order by t.number) from public.teams t where t.class_id=c.id),'[]'::jsonb)) into out from public.classes c where c.id=p_id and c.owner_id=auth.uid(); if out is null then raise exception '클래스를 찾을 수 없습니다'; end if; return out; end $$;
create function public.class_landing(p_token text) returns jsonb language plpgsql security definer set search_path=public,auth as $$ declare out jsonb; begin select jsonb_build_object('name',c.name,'teams',coalesce((select jsonb_agg(jsonb_build_object('id',t.id,'number',t.number) order by t.number) from public.teams t where t.class_id=c.id),'[]'::jsonb)) into out from public.classes c where c.invite_token=p_token; if out is null then raise exception '유효하지 않은 클래스 링크입니다'; end if; return out; end $$;
create function public.join_team(p_token text,p_team uuid,p_code text) returns jsonb language plpgsql security definer set search_path=public,auth as $$ declare t public.teams; members int; begin if auth.uid() is null then raise exception '로그인이 필요합니다'; end if; select teams.* into t from public.teams join public.classes c on c.id=teams.class_id where teams.id=p_team and c.invite_token=p_token for update of teams; if not found or t.join_code <> upper(trim(p_code)) then raise exception '조 링크 또는 입장 코드가 올바르지 않습니다'; end if; if not exists(select 1 from public.team_members where team_id=t.id and user_id=auth.uid()) then select count(*) into members from public.team_members where team_id=t.id; if members >= 2 then raise exception '이 조에는 이미 2명이 참여하고 있습니다'; end if; insert into public.team_members(team_id,user_id) values(t.id,auth.uid()); end if; return jsonb_build_object('id',t.id,'number',t.number,'doc',t.doc,'version',t.version); end $$;
create function public.get_team(p_id uuid) returns jsonb language plpgsql security definer set search_path=public,auth as $$ declare t public.teams; begin select * into t from public.teams where id=p_id; if not found or not (exists(select 1 from public.team_members where team_id=p_id and user_id=auth.uid()) or exists(select 1 from public.classes where id=t.class_id and owner_id=auth.uid() and public.is_admin())) then raise exception '접근 권한이 없습니다'; end if; return jsonb_build_object('id',t.id,'number',t.number,'doc',t.doc,'version',t.version); end $$;
create function public.save_team(p_id uuid,p_doc jsonb,p_version int) returns jsonb language plpgsql security definer set search_path=public,auth as $$ declare t public.teams; begin if not exists(select 1 from public.team_members where team_id=p_id and user_id=auth.uid()) then raise exception '조 참여자만 작성할 수 있습니다'; end if; if jsonb_typeof(p_doc)<>'object' or pg_column_size(p_doc)>200000 then raise exception '입력 내용이 올바르지 않습니다'; end if; update public.teams set doc=p_doc,version=version+1,updated_at=now() where id=p_id and version=p_version returning * into t; if not found then raise exception '다른 기기에서 먼저 저장했습니다. 새로고침해 최신 내용을 확인해 주세요'; end if; return jsonb_build_object('version',t.version); end $$;
revoke all on function public.is_admin(),public.make_class(text,int),public.admin_classes(),public.admin_class(uuid),public.class_landing(text),public.join_team(text,uuid,text),public.get_team(uuid),public.save_team(uuid,jsonb,int) from public;
grant execute on function public.is_admin(),public.make_class(text,int),public.admin_classes(),public.admin_class(uuid),public.join_team(text,uuid,text),public.get_team(uuid),public.save_team(uuid,jsonb,int) to authenticated;
grant execute on function public.class_landing(text) to anon,authenticated;
